 function node(type,id,title,x,y,imgs=[]) { return {id,type,title,x,y,w:type==='import'?324:440,pictureH:type==='import'?175:220,images:clone(imgs),index:0,prompt:'保留参考图中的人物关系与列车结构。冬日的站台，冷灰色调与车窗的温暖灯光形成对比，细腻胶片质感，自然写实，电影剧照。',model:'gpt-image-2.5-flare',provider:'示例供应商',ratio:'16:9',resolution:'2K',quality:'默认',count:1,system:'',thinking:'接口默认',search:false,params:'{}',status:imgs.length?'success':'idle',dirty:false,disabled:false,missing:false,scale:100,width:1536,height:864,keepRatio:true,resizeMode:'等比缩放',temperature:0,tint:0,saturation:100,whiteBalance:'原始',prefix:'冬日站台',url:'',advancedExpanded:false}; }
 const get = id => S.nodes.find(n=>n.id===id);
