 function requestSize(n){if(n.ratio==='自定义')return`${n.width} × ${n.height}`;const side=({'1K':1024,'2K':2048,'4K':4096})[n.resolution]||2048;const [a,b]=(n.ratio==='由模型决定'?'16:9':n.ratio).split(':').map(Number);return a>=b?`${side} × ${Math.round(side*b/a)}`:`${Math.round(side*a/b)} × ${side}`;}
 const locked = n => !!(isRunning(n)||S.running&&S.edges.some(e=>e.from===n?.id&&S.running.ids.includes(e.to)));
