 function canConnect(from,to,port){if(!from||!to)return'端口来源已不存在';if(from.id===to.id)return'不能连接到自身';if(locked(from)||locked(to))return'运行端点和关联来源受保护';if(!ports(to).some(([key])=>key===port)||outputType(from)!==inputType(port))return'输入与输出类型不兼容';if(S.edges.some(e=>e.from===from.id&&e.to===to.id&&e.port===port))return'此连接已存在';const visit=(id,seen=new Set())=>{if(id===from.id)return true;if(seen.has(id))return false;seen.add(id);return S.edges.filter(e=>e.from===id).some(e=>visit(e.to,seen));};if(visit(to.id))return'此连接会形成循环';if(to.type==='generate'&&port==='reference'&&refCount(to)+(from.disabled?0:from.images.length)>8)return'示例模型参考容量为 8 张，请减少来源';return'';}
 function connect(from,to,port){const error=canConnect(from,to,port);if(error)return toast(error);snapshot();if(!multiInput(to,port))S.edges=S.edges.filter(e=>!(e.to===to.id&&e.port===port));S.edges.push({from:from.id,to:to.id,port});edited(to);S.activePort=null;renderNodes();renderPanel();toast('已连接端口，其他连接保持不变');}
