 function statusText(n) {if(n.missing)return'原图缺失';return {idle:'尚未生成',waiting:'等待上游',running:`生成中 · ${n.progress||0}%`,success:'已完成',failed:n.error||'生成失败',cancelled:'已取消'}[n.status]||'就绪';}
