  'parameter-front':()=>{if(!S.panelOpen){if(selected())openNode(S.selected);else return toast('先选择要编辑的节点');}bring('parameter');},'agent-front':()=>openAgent(),'agent-toggle':()=>{S.agentOpen=!S.agentOpen;renderAgent();if(S.agentOpen)bring('agent');},'agent-close':()=>{S.agentOpen=false;renderAgent();},optimize:()=>optimize(), 'edit-result':b=>{if(b.dataset.id)openNode(b.dataset.id);optimize(true);},'agent-suggest':()=>{const n=selected()||get('n3');$('#agent-input').value=`@${n.title}[${n.id}] 保留构图，让车窗光线更温暖。`;},'agent-mention':()=>{const n=selected();if(n)$('#agent-input').value+=` @${n.title}[${n.id}]`;else toast('先选择一个节点');},'agent-send':sendAgent,'agent-apply':()=>applyPlan(false),'agent-apply-run':()=>applyPlan(true),'attachment-remove':b=>{S.attachments.splice(+b.dataset.index,1);renderAgent();},
