  download:b=>download(currentImage(get(b.dataset.id)||selected()),selected()?.prefix),'download-batch':()=>{selected()?.images.forEach((im,i)=>setTimeout(()=>download(im,selected().prefix+'_'+(i+1)),i*150));},'use-reference':b=>{const n=get(b.dataset.id)||selected(),im=currentImage(n);if(im)S.attachments.push(clone(im));openAgent();toast('已准备当前单张图片为助手附件，尚未发送或更改节点连线');},
  'new-menu':()=>openNewMenu(),'new-node':b=>{const type=b.dataset.type;$('#general-dialog').close();newNode(type,S.newCoords);S.newCoords=null;},save:saveWorkflow,workflows:()=>dialog('演示工作流',`<p>当前：冬日站台 · 独立原型</p><div class="setting-bar">${btn('save','导出演示工作流')}${btn('import-workflow','导入演示 JSON')}${btn('reset','重置示例')}</div><p class="helper">正式工作流不会被读取或修改。</p>`),'import-workflow':()=>$('#workflow-upload').click(),
  help,history:()=>dialog('本次原型操作记录',`<ol class="history-list">${S.log.map(l=>`<li><time>${esc(l.time)}</time> ${esc(l.message)}</li>`).join('')}</ol>`),state:()=>dialog('演示状态 · 所有数据仅在内存',`<pre class="state-json">${esc(JSON.stringify({scene:S.scenario,selected:S.selected,panel:{open:S.panelOpen,expanded:S.expanded,group:S.group,width:S.panelWidth},camera:S.camera,agentOpen:S.agentOpen,nodes:S.nodes.map(n=>({id:n.id,type:n.type,status:n.status,batch:n.images.length,index:n.index,dirty:n.dirty,missing:n.missing,disabled:n.disabled})),connections:S.edges,undoSteps:S.undo.length},null,2))}</pre>`),'dialog-close':()=>$('#general-dialog').close(),reset:()=>{$('#general-dialog').close();initial();toast('示例画布已重置');},'fail-next':()=>{S.failNext=true;$('#general-dialog').close();toast('下一次点击生成会模拟失败，可查看完整错误后重试');},error:b=>dialog('本轮完整错误',`<pre class="error-detail">${esc(errorDetails(get(b.dataset.id)||selected()))}</pre>${btn('dialog-close','返回')}`),
