  upload:b=>{S.uploadTarget=b.dataset.id||S.selected;$('#image-upload').click();},'agent-attach':()=>{S.uploadTarget='agent';$('#image-upload').click();},'import-url':()=>{renderPanel();panel.querySelector('[data-field="url"]')?.focus();},'load-url':()=>{const n=selected();if(!/^https?:\/\//.test(n.url))return toast('请输入 http 或 https 图片链接');snapshot();n.images=[{src:n.url,label:'URL 参考图',width:0,height:0}];n.status='success';renderNodes();renderPanel();toast('仅在此原型尝试显示链接，不进入正式媒体存储');},restore:b=>{const n=get(b.dataset.id)||selected();snapshot();n.missing=false;if(!n.images.length)n.images=[clone(pictures[1])];renderNodes();renderPanel();toast('已恢复示例原图，连接和位置不变');},
  'pick-color':()=>{S.picking=!S.picking;renderPanel();toast(S.picking?'取色已开启，请点击原图':'已退出取色');},'color-reset':()=>{snapshot();Object.assign(selected(),{temperature:0,tint:0,saturation:100,whiteBalance:'原始'});renderNodes();renderPanel();},'local-zoom':b=>{const n=get(b.dataset.id)||selected();n.localZoom=Math.max(1,Math.min(3,(n.localZoom||1)+.2*Number(b.dataset.value)));document.querySelector(`[data-node="${n.id}"] .node-picture > img`).style.transform=`scale(${n.localZoom})`;},'local-reset':b=>{const n=get(b.dataset.id)||selected();n.localZoom=1;renderNodes();},'compare-editor':()=>preview(selected()),'swap-compare':()=>{const n=selected();snapshot();n.images.reverse();renderNodes();},'add-input':()=>{toast('原型保留动态输入入口：从其他图片输出端口连到此节点即可增加来源');},resume:()=>toast('已演示恢复入口；此独立原型没有真实远端任务，不发送轮询请求。'),'video-info':()=>dialog('保存节点 · 视频功能保留',`<p>正式保存节点继续支持视频预览、播放控制与保存。这个独立原型使用静态图片样例，不连接真实视频生成。</p>${btn('dialog-close','返回')}`),
  'result-more':b=>{const n=get(b.dataset.id)||selected();dialog('图片更多操作',`${btn('copy-node','复制节点',`data-id="${n.id}"`)} ${btn('clone-node','克隆并保留参考来源',`data-id="${n.id}"`)} ${btn('download','下载当前原图',`data-id="${n.id}"`)}`);},'node-more':b=>{const n=get(b.dataset.id);dialog(n.title,`<div class="setting-bar">${btn('copy-node','复制节点',`data-id="${n.id}"`)}${btn('clone-node','克隆并保留上游连接',`data-id="${n.id}"`)}${btn('toggle-disable',n.disabled?'启用':'禁用',`data-id="${n.id}"`)}${btn('delete-node','删除节点',`data-id="${n.id}"`)}</div><p class="helper">演示操作可以撤销，不影响正式工作流。</p>`);},'copy-node':b=>{S.clipboard=clone(get(b.dataset.id)||selected());toast('节点已复制，可用 Ctrl+V 粘贴独立副本');if($('#general-dialog').open)$('#general-dialog').close();},'clone-node':b=>duplicate(get(b.dataset.id)||selected(),true),'delete-node':b=>removeNode(get(b.dataset.id)||selected()),'toggle-disable':b=>{const n=get(b.dataset.id);if(locked(n))return toast('运行节点和关联来源受保护');snapshot();n.disabled=!n.disabled;$('#general-dialog').close();renderNodes();renderPanel();},
